import {training} from '../functions/game/training.js';
import {offlineRounds} from './device.js';
import './style.css';
import {createIcons,Compass,Feather,Hammer,ChartNoAxesCombined,Zap,Gem,Radio,MessagesSquare,Swords,HeartHandshake,Settings,Crown,Map,ScrollText,ShieldCheck,BookOpen,UserRound,Lock,ArrowRight,Check,Flame,Shield,KeyRound,Star,Download,LogOut,Volume2,VolumeX,ChevronRight,ExternalLink,Cloud,HardDrive,RefreshCw} from 'lucide';
import {worlds,missions,guides,steps,optionNames} from '../functions/game/content.js';
import {level,guideLevel,worldOpen,missionOpen,missionState,bossReady,bossChallenge} from '../functions/game/engine.js';
import * as api from './backend.js';
const icons={Compass,Feather,Hammer,ChartNoAxesCombined,Zap,Gem,Radio,MessagesSquare,Swords,HeartHandshake,Settings,Crown,Map,ScrollText,ShieldCheck,BookOpen,UserRound,Lock,ArrowRight,Check,Flame,Shield,KeyRound,Star,Download,LogOut,Volume2,VolumeX,ChevronRight,ExternalLink,Cloud,HardDrive,RefreshCw};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
let state=api.session,selectedWorld=0,selectedMission='m1',selectedGuide='strategist',busy=false,installPrompt=null,queue=[],vaultFilter='all';
let prefs;try{prefs=JSON.parse(localStorage.getItem('oyo-preferences')||'{}')}catch{prefs={}};
let resourceDraft=null;
let communityMessages=[],communityStop=null,communityUid=null,communityReports=[];
let adminOverview=null;
let hydrated=false;
let view=location.hash.slice(1)||'map';
const routes=['map','mission','guides','boss','vault','progress','resources','membership','profile','review','community','admin'];
if(!routes.includes(view))view='map';
function go(next){location.hash=next;if(view===next)render();}
window.addEventListener('hashchange',()=>{view=routes.includes(location.hash.slice(1))?location.hash.slice(1):'map';render();$('#main')?.focus();});
window.addEventListener('oyo-error',e=>notify(e.detail,true));
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render();});
function notify(text,error=false){const n=$('#notice');n.textContent=text;n.className=error?'show error':'show';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.className='',6500);}
function sound(){if(!prefs.sound)return;try{const c=new (window.AudioContext||window.webkitAudioContext)();const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.setValueAtTime(523,c.currentTime);o.frequency.setValueAtTime(784,c.currentTime+.12);g.gain.setValueAtTime(.04,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.4);o.start();o.stop(c.currentTime+.4);o.onended=()=>c.close();}catch{}}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('busy');document.body.setAttribute('aria-busy','true');try{await fn();}catch(e){notify(e.message||'Something went wrong. Try again.',true);}finally{busy=false;document.body.classList.remove('busy');document.body.removeAttribute('aria-busy');}}
const currentMission=()=>missions.find(m=>missionOpen(state.game,m.id)&&missionState(state.game,m.id).status!=='verified');
function nav(label,id,symbol){return `<button class="nav-item ${view===id?'active':''}" aria-label="${label}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${view===id?icon('ChevronRight'):''}</button>`;}
function title(kicker,text,extra=''){return `<header class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${text}</h1></div>${extra}</header>`;}
function render(){const g=state.game;document.documentElement.classList.toggle('reduce-motion',!!prefs.motion);$('#app').innerHTML=`
 <aside class="sidebar"><a class="brand" href="#map" aria-label="OYO Unlocked world map">${icon('Crown')}<strong>OYO</strong><span>UNLOCKED</span><small>OWN YOUR OPTIONS</small></a>
 <button class="player" data-nav="profile"><span class="avatar">${icon(g.profile.avatar)}</span><span><b>${esc(g.profile.name)}</b><small>Level ${level(g)} · ${esc(g.profile.path)}</small></span></button>
 <nav aria-label="Game navigation">${nav('World map','map','Map')}${nav('Missions','mission','ScrollText')}${nav('AI Guides','guides','Compass')}${nav('Boss battles','boss','Swords')}${nav('Proof Vault','vault','ShieldCheck')}${nav('Community','community','MessagesSquare')}${nav('My progress','progress','ChartNoAxesCombined')}<div class="nav-divider"></div>${nav('Resource Hub','resources','BookOpen')}${nav('Membership','membership','Crown')}${nav('Character & settings','profile','Settings')}${state.isOwner?nav('Owner Admin','admin','Shield'):''}</nav>
 <div class="sidebar-foot"><span class="save-badge">${icon(api.cloud?'Cloud':'HardDrive')}${api.cloud?(state.user?'Cloud adventure':'Sign in to save'):'Saved on this device'}</span><p>Real skills.<br>More possibilities.</p><small>OYO: UNLOCKED · v0.1</small></div></aside>
 <div class="game-shell"><header class="hud"><div class="location">${icon('Compass')}<span>YOUR ADVENTURE <b>${esc(worlds[selectedWorld].name)}</b></span></div><div class="xp-hud"><span>LEVEL ${level(g)}</span><div><div class="xp-label"><b>${g.xp%500} / 500 XP</b><small>NEXT LEVEL</small></div><progress max="500" value="${g.xp%500}" aria-label="Experience toward next level"></progress></div></div><div class="hud-stat">${icon('Zap')}<b>${Object.values(g.skills).reduce((a,b)=>a+b,0)}</b><small>SKILLS</small></div><div class="hud-stat gold">${icon('KeyRound')}<b>${g.options.length}</b><small>OPTIONS</small></div><button class="icon-button" data-nav="profile" aria-label="Character and settings">${icon('UserRound')}</button></header>
 ${!navigator.onLine?'<div class="mode-banner">Offline · '+(api.cloud?'Your cloud adventure needs a connection.':'Your device adventure remains available. Live services need internet.')+'</div>':''}
 ${api.cloud&&!state.user?'<div class="mode-banner">Sign in to begin your cloud adventure. <button data-nav="profile">Open account</button></div>':''}
 ${!state.ready?`<div class="mode-banner"><b>Loading</b> · Explore the screens. Loading your saved adventure. <button data-nav="profile">Connection details</button></div>`:''}<main id="main" tabindex="-1">${state.announcement?.enabled?`<aside class="callout"><b>${esc(state.announcement.title)}</b><p>${esc(state.announcement.body)}</p></aside>`:''}${!state.ready&&view==='profile'?`<section class="panel"><p class="eyebrow">OYO: UNLOCKED</p><h1>${state.connectionError?'Live connection required':'Connecting to your adventure…'}</h1><p>${esc(state.connectionError||'Loading your account connection.')}</p><p>This version requires the live Firebase services. No simulated progress or AI responses are available.</p></section>`:({map:mapView,mission:missionView,guides:guidesView,boss:bossView,vault:vaultView,progress:progressView,resources:resourcesView,membership:membershipView,profile:profileView,review:reviewView,community:communityView,admin:adminView}[view]||mapView)()}</main>
 <footer class="game-footer"><span>${icon('ShieldCheck')} Progress is earned through proof.</span><span>${api.cloud?'Cloud mode':'Device adventure · self-reviewed proof'} · No income guarantees</span></footer></div>`;
 createIcons({icons,attrs:{'stroke-width':1.6}});bind();syncCommunity();if(!state.ready){document.querySelectorAll('form input,form textarea,form select,form button,[data-step]').forEach(el=>el.disabled=true);}}
function mapView(){const g=state.game,w=worlds[selectedWorld],open=worldOpen(g,w.index),done=missions.filter(m=>missionState(g,m.id).status==='verified').length;
 return title('THE BUSINESS WORLDS','Your next chapter awaits.',`<span class="season-tag">${icon('Star')} CHAPTER 01 · THE BEGINNING</span>`)+`
 <div class="map-layout"><section class="world-map" aria-label="Nine business worlds"><div class="map-caption"><span class="eyebrow">THE REAL-WORLD ADVENTURE</span><span>${done} / 18 missions verified</span></div><div class="map-art"><img src="/worlds.webp" alt="Nine floating obsidian and gold citadels linked by glowing violet bridges" fetchpriority="high"><div class="map-worlds">${worlds.map(x=>`<button class="world-node ${selectedWorld===x.index?'selected':''} ${worldOpen(g,x.index)?'available':'locked'} ${g.bosses[x.id]?.won?'conquered':''}" data-world="${x.index}" aria-pressed="${selectedWorld===x.index}" aria-label="World ${x.index+1}, ${x.name}, ${worldOpen(g,x.index)?'available':'locked'}"><span class="world-sigil">${icon(g.bosses[x.id]?.won?'Check':worldOpen(g,x.index)?x.icon:'Lock')}</span><span class="world-label"><small>WORLD 0${x.index+1}</small><b>${x.name}</b></span></button>`).join('')}</div></div><div class="map-bottom"><span>${icon('Compass')} Select a world to explore</span><span>${icon('Lock')} Build. Prove. Unlock.</span></div></section>
 <aside class="quest-panel"><div class="quest-top"><span class="eyebrow">${open?'YOUR NEXT DESTINATION':'UNDISCOVERED WORLD'}</span><span class="world-number">0${w.index+1}</span></div><div class="large-sigil">${icon(w.icon)}</div><h2>${w.name}</h2><p class="muted">${w.tagline}.</p><div class="quest-rule"></div><p class="eyebrow">${open?'WORLD OBJECTIVES':'TO UNLOCK THIS WORLD'}</p>${open?missions.filter(m=>m.world===w.index).map(m=>`<button class="objective" data-mission="${m.id}" ${missionOpen(g,m.id)?'':'disabled'}><span class="objective-status">${icon(missionState(g,m.id).status==='verified'?'Check':missionOpen(g,m.id)?'ScrollText':'Lock')}</span><span><b>${m.title}</b><small>${missionState(g,m.id).status==='verified'?'Verified':missionState(g,m.id).status==='pending'?'Awaiting verification':missionOpen(g,m.id)?`${m.xp} XP · ready to play`:'Verify the previous mission'}</small></span></button>`).join(''):`<p>Verify both missions and defeat <b>${worlds[w.index-1].boss}</b> in ${worlds[w.index-1].name}.</p>`}
 <button class="boss-objective" data-nav="boss">${icon('Swords')}<span><small>WORLD BOSS</small><b>${w.boss}</b></span>${icon(g.bosses[w.id]?.won?'Check':bossReady(g,w.index)?'ArrowRight':'Lock')}</button>
 <button class="primary wide" data-continue ${!open?'disabled':''}>${g.bosses[w.id]?.won?'Revisit world':bossReady(g,w.index)?'Enter boss battle':'Continue adventure'} ${icon('ArrowRight')}</button><span class="quest-reward">${icon('Gem')} EARN THE ${w.name.toUpperCase()} CREST</span></aside></div>
 <section class="journey-strip" aria-label="Mission progression">${steps.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s}</b>${i<6?icon('ChevronRight'):icon('KeyRound')}</div>`).join('')}</section>
 <section class="guide-preview"><div><p class="eyebrow">YOU DON'T GO ALONE</p><h2>Meet your Guides</h2><p>They grow as you do.</p></div><div class="guide-mini-row">${guides.map(x=>`<button class="guide-mini" data-guide="${x.id}"><span class="guide-orb">${icon(x.icon)}</span><b>${x.name}</b><small>LVL ${guideLevel(g,x.id)}</small></button>`).join('')}</div></section>`;
}
function missionView(){const g=state.game;let m=missions.find(x=>x.id===selectedMission)||missions[0];if(!missionOpen(g,m.id)){m=currentMission()||missions[0];selectedMission=m.id;}const s=missionState(g,m.id),w=worlds[m.world];
 let body='';if(s.step===0)body=`<span class="chapter-icon">${icon('BookOpen')}</span><h2>A small lesson. A real next step.</h2><p class="lesson">${m.lesson}</p><section class="training-module"><h3>${esc(training[m.world].title)}</h3>${training[m.world].teach.map(t=>`<p>${esc(t)}</p>`).join('')}<div class="callout"><b>Worked example</b><p>${esc(training[m.world].example)}</p></div><h3>Your workshop</h3><p>${esc(training[m.world].workshop)}</p><p><b>Quality check:</b> ${esc(training[m.world].check)}</p></section><div class="callout"><b>Your field mission</b><p>${m.irl}</p></div><button class="primary" data-step="0">Ready to practise ${icon('ArrowRight')}</button>`;
 if(s.step===1)body=`<h2>Put the idea to work.</h2><p class="lesson">${m.question}</p><form id="practice-form"><fieldset><legend>Choose one answer</legend>${m.answers.map((a,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required><span>${a}</span></label>`).join('')}</fieldset><button class="primary">Check my answer ${icon('ArrowRight')}</button></form>`;
 if(s.step===2)body=`<h2>Build your first version.</h2><p>Use this framework and make it specific to your business.</p><form id="build-form"><label for="draft">Your business asset <small>60–6,000 characters</small></label><textarea id="draft" name="draft" minlength="60" maxlength="6000" required rows="10">${esc(sessionStorage.getItem('draft-'+(state.user?.uid||'signed-out')+'-'+m.id)||s.draft||m.template)}</textarea><button class="primary">Save asset & continue ${icon('ArrowRight')}</button></form>`;
 if(s.step===3)body=`<h2>Take it into the real world.</h2><p class="lesson">${m.irl}</p><details><summary>Your saved asset</summary><p class="prewrap">${esc(s.draft)}</p></details><div class="callout"><b>Keep it respectful.</b><p>Ask permission, remove private details, and report what really happened. Small results and thoughtful “no” decisions count.</p></div><form id="irl-form"><label class="answer"><input type="checkbox" name="confirmed" required><span>I completed the real action and have evidence to submit.</span></label><button class="primary">Prepare my proof ${icon('ArrowRight')}</button></form>`;
 if(s.step===4)body=`<h2>Show what you built.</h2>${s.feedback?`<p class="callout">Reviewer feedback: ${esc(s.feedback)}</p>`:''}<p>Explain the real action. Redact names, messages, and private information before uploading.</p><form id="proof-form"><label for="summary">What did you do, and what happened?</label><textarea name="summary" id="summary" minlength="60" maxlength="6000" required rows="4" placeholder="Describe the action, context, and actual outcome. Minimum 60 characters."></textarea>${m.criteria.map((c,i)=>`<label for="evidence-${i}">${c}</label><textarea id="evidence-${i}" name="evidence-${i}" rows="2" minlength="20" maxlength="2000" required placeholder="Show how your evidence meets this criterion (20+ characters)."></textarea>`).join('')}<label for="proof-url">Evidence link <small>Optional · HTTPS</small></label><input id="proof-url" name="url" type="url" placeholder="https://"><label for="file">Supporting file <small>Optional · JPG, PNG, WebP or PDF · up to 5 MB</small></label><input id="file" name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"><button class="primary">Submit to Proof Vault ${icon('ShieldCheck')}</button></form>`;
 if(s.step===5)body=`<div class="outcome">${icon('ShieldCheck')}<p class="eyebrow">PROOF RECEIVED</p><h2>One step from your unlock.</h2><p>${api.cloud?'Your evidence is waiting for an authorised reviewer. You can explore Guides while you wait.':'Check every criterion against your actual work. Self-review unlocks your device adventure; it is not independent or owner verification.'}</p>${api.cloud?'<button class="primary" data-refresh>Check review status</button>':`<button class="primary" data-simulate="${s.proofId}">Confirm my evidence is complete ${icon('Check')}</button>`}<button class="secondary" data-nav="vault">View Proof Vault</button></div>`;
 if(s.step===6)body=`<div class="outcome success">${icon('Crown')}<p class="eyebrow">${api.cloud?'MISSION VERIFIED':'MISSION SELF-REVIEWED'}</p><h2>You earned your next step.</h2><div class="earned">+${m.xp} XP <span>+1 ${w.skill} skill</span></div><p>${esc(s.feedback)}</p><button class="primary" data-next>Continue adventure ${icon('ArrowRight')}</button><button class="secondary" data-nav="vault">View your proof</button></div>`;
 return title(`WORLD 0${w.index+1} / MISSION ${m.id.slice(1).padStart(2,'0')}`,m.title,`<span class="reward-pill">${icon('Zap')} ${m.xp} XP</span>`)+`<div class="mission-layout"><aside class="mission-rail">${steps.map((x,i)=>`<div class="step ${i===s.step?'current':''} ${i<s.step?'complete':''}"><span>${i<s.step?icon('Check'):i+1}</span><b>${x}</b></div>`).join('')}<p>Your next mission unlocks after proof is verified.</p><button class="secondary wide" data-nav="map">Return to world map</button></aside><section class="panel mission-content">${body}</section><aside class="mission-help"><div class="guide-orb">${icon(guides.find(x=>x.id===w.guide).icon)}</div><h3>${guides.find(x=>x.id===w.guide).name}</h3><p>LVL ${guideLevel(g,w.guide)} · YOUR GUIDE</p><p>Make it specific. A small, honest action beats a perfect plan.</p><button class="secondary wide" data-guide="${w.guide}">Ask your Guide</button><h3>Proof checklist</h3><ul>${m.criteria.map(c=>`<li>${c}</li>`).join('')}</ul></aside></div>`;
}
function guidesView(){const g=state.game,guide=guides.find(x=>x.id===selectedGuide);return title('YOUR PARTY','Six Guides. One shared adventure.')+`<div class="guide-picker">${guides.map(x=>`<button data-select-guide="${x.id}" class="guide-card ${x.id===guide.id?'selected':''}" aria-pressed="${x.id===guide.id}"><span class="guide-orb">${icon(x.icon)}</span><b>${x.name}</b><small>${x.role}</small><span class="gold">LEVEL ${guideLevel(g,x.id)}</span></button>`).join('')}</div><div class="two-col"><section class="panel"><p class="eyebrow">${guide.role.toUpperCase()}</p><h2>Talk with ${guide.name}</h2><div class="chat-log" aria-label="Conversation">${(g.chats[guide.id]||[]).map(c=>`<div class="chat ${c.role==='user'?'you':''}"><small>${c.role==='user'?'YOU':guide.name.toUpperCase()}</small><p class="prewrap">${esc(c.text)}</p></div>`).join('')||`<div class="chat"><p>Bring a draft, a question, or a place you feel stuck. Your Guide's capabilities grow with verified work.</p></div>`}</div><form id="chat-form"><label for="message">Your message</label><textarea name="message" id="message" minlength="3" maxlength="2000" required rows="3" placeholder="Help me think through my next action…"></textarea><button class="primary">Send to ${guide.name} ${icon('ArrowRight')}</button></form><p class="fine">${api.cloud?'Powered by your OYO Compass connection. Your question and game context are processed to create the reply.':'Offline strategy library · Connect through Online account for personalized OYO Compass AI.'}</p></section><aside class="panel"><div class="large-sigil">${icon(guide.icon)}</div><h2>Guide level ${guideLevel(g,guide.id)}</h2><progress max="300" value="${(g.guideXp[guide.id]||0)%300}" aria-label="Guide level progress"></progress><p>${300-(g.guideXp[guide.id]||0)%300} Guide XP to next level</p><ul class="capabilities"><li>Level 1 · Explain & encourage</li><li>Level 3 · Compare & challenge</li><li>Level 6 · Diagnose & experiment</li></ul><p class="muted">Verify missions in this Guide's worlds to grow their capabilities. Chatting alone doesn't award XP.</p></aside></div>`;}
function bossView(){const g=state.game,w=worlds[selectedWorld],b=g.bosses[w.id]||{round:0,attempts:0},ready=bossReady(g,w.index);return title(`WORLD 0${w.index+1} / BOSS BATTLE`,w.boss,`<span class="reward-pill">${icon('Swords')} TIER ${w.index+1}</span>`)+`<section class="boss-stage"><div class="boss-aura">${icon(b.won?'Crown':'Swords')}</div><p class="eyebrow">${b.won?'WORLD CONQUERED':ready?'THE CHALLENGE EVOLVES':'PROOF REQUIRED'}</p><h2>${b.won?'A new possibility is yours.':w.boss}</h2><div class="boss-health" aria-label="Boss rounds completed">${[0,1,2].map(i=>`<span class="${i<b.round?'hit':''}">${i<b.round?'COMPLETE':`ROUND ${i+1}`}</span>`).join('')}</div>${!ready?`<p>Verify both ${w.name} missions to unlock this battle.</p><button class="primary" data-nav="map">Return to your missions</button>`:b.won?`<p>${esc(optionNames[w.index])} unlocked. This is a prepared path to explore, not a promised financial result.</p><button class="primary" data-next-world>${w.index<8?'Explore the next world':'View your achievements'} ${icon('ArrowRight')}</button>`:`<p class="boss-prompt">${esc(bossChallenge(g,w))}</p><form id="boss-form">${!api.cloud?`<fieldset><legend>${esc(offlineRounds[Math.min(b.round,2)].objection)}</legend>${offlineRounds[Math.min(b.round,2)].options.map((o,i)=>`<label class="answer"><input type="radio" name="choice" value="${i}" required><span>${esc(o)}</span></label>`).join('')}</fieldset>`:''}<label for="boss-answer">Your move <small>Respond to the objection, explain your next move, and how you will check fit</small></label><textarea id="boss-answer" name="answer" minlength="40" maxlength="3000" required rows="5" placeholder="What would you say to this person? What is your next step, and why?"></textarea><button class="primary">Make your move ${icon('Swords')}</button></form><p class="fine">${api.cloud?'Live OYO Compass assessment.':'Offline strategy challenge · evaluates your selected choice. Written reflections are saved, not AI-assessed.'} Difficulty increases each round.</p>`}${b.history?.length?`<details open><summary>Latest battle feedback · ${b.attempts} moves</summary><p>${esc(b.history.at(-1).feedback)}</p></details>`:''}</section>`;}
function vaultView(){const items=state.proofs.filter(p=>vaultFilter==='all'||p.status===vaultFilter);return title('REAL ACTIONS. A RECORD YOU KEEP.','The Proof Vault',`<button class="secondary" data-export>${icon('Download')} Export record</button>`)+`<div class="filter-row" aria-label="Filter proofs">${['all','pending','verified','rejected'].map(f=>`<button class="chip ${vaultFilter===f?'active':''}" data-filter="${f}" aria-pressed="${vaultFilter===f}">${f==='all'?'All proof':f}</button>`).join('')}</div><div class="vault-grid">${items.map(p=>`<article class="panel proof-card"><div class="proof-head"><span class="status ${p.status}">${icon(p.status==='verified'?'ShieldCheck':'ScrollText')}${p.status==='verified'&&!api.cloud?'self-reviewed':p.status}</span><small>${new Date(p.createdAt).toLocaleDateString()}</small></div><h2>${esc(missions.find(m=>m.id===p.missionId)?.title)}</h2><p>${esc(p.summary)}</p><details><summary>View criteria & review</summary>${(p.evidence||[]).map((e,i)=>`<p><b>${esc(missions.find(m=>m.id===p.missionId)?.criteria[i])}</b><br>${esc(e)}</p>`).join('')}<p>${esc(p.feedback||'Awaiting review.')}</p></details>${p.url?`<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open submitted link ${icon('ExternalLink')}</a>`:''}${p.hasFile||p.attachment?`<button class="secondary" data-file="${p.id}">${icon('Download')} ${esc(p.fileName||p.attachment.name)}</button>`:''}${p.status==='pending'&&!api.cloud?`<button class="primary" data-simulate="${p.id}">Confirm my evidence is complete</button>`:''}</article>`).join('')||`<div class="empty-state">${icon('ShieldCheck')}<h2>Your actions belong here.</h2><p>${vaultFilter==='all'?'Complete your first mission and submit proof to start your collection.':'No proofs match this filter yet.'}</p><button class="primary" data-nav="mission">Open mission ${icon('ArrowRight')}</button></div>`}</div>`;}
function progressView(){const g=state.game;return title('YOUR CHARACTER IS EVOLVING','Look at what you’ve built.')+`<div class="stats-grid"><div class="panel"><span>TOTAL EXPERIENCE</span><strong>${g.xp}</strong><small>Level ${level(g)}</small></div><div class="panel"><span>COMPLETED MISSIONS</span><strong>${Object.values(g.missions).filter(x=>x.status==='verified').length}<small> / 18</small></strong><small>${api.cloud?'Reviewed evidence':'Self-reviewed on this device'}</small></div><div class="panel"><span>WORLDS CONQUERED</span><strong>${Object.values(g.bosses).filter(x=>x.won).length}<small> / 9</small></strong><small>Every world opens a possibility</small></div></div><div class="two-col"><section class="panel"><h2>Your skill tree</h2>${['Strategy','Creativity','Building','Connection','Analysis','Momentum'].map(s=>`<div class="skill-line"><span>${s}</span><progress max="6" value="${g.skills[s]||0}" aria-label="${s} skill points"></progress><b>${g.skills[s]||0}</b></div>`).join('')}<h2 class="mt">Achievement collection</h2><div class="badges">${g.achievements.map(a=>`<span>${icon('Crown')}${esc(a)}</span>`).join('')||'<p class="muted">Your first crest is waiting beyond your first proof.</p>'}</div></section><section class="panel"><h2>Your options</h2><p>Prepared paths you can explore. These are game unlocks, not verified income sources.</p>${optionNames.map(o=>`<div class="option-line ${g.options.includes(o)?'earned-option':''}">${icon(g.options.includes(o)?'KeyRound':'Lock')}<span>${o}</span></div>`).join('')}</section></div>`;}
function resourceConfig(){let mainUrl='';try{if(new URL(import.meta.env.VITE_LWA_URL).protocol==='https:')mainUrl=import.meta.env.VITE_LWA_URL;}catch{}return state.resources||{mainUrl,mainTitle:import.meta.env.VITE_LWA_LABEL||'Explore LWA',products:[],revision:0};}
function resourcesView(){const cfg=resourceConfig(),draft=resourceDraft||cfg;return title('THE RESOURCE HUB','Tools for your next move.')+`<div class="two-col"><section class="panel"><span class="large-sigil">${icon('BookOpen')}</span><h2>Your field kit</h2><p>Everything required to progress is in OYO. Use these frameworks for your next real action.</p><details open><summary>Discovery & closing questions</summary><p>What prompted you to look at this now? How do you handle it today? What is that costing in time or effort? What would a useful improvement look like? Who needs to be involved in a decision?</p><p>When there is a fit: “Based on what you shared, this scope addresses [specific need]. What would you need to feel comfortable deciding whether it fits?”</p></details><details><summary>Work through an objection</summary><p>Acknowledge it. Ask what is behind it. Clarify whether the issue is fit, timing, cost, trust, or authority. Give relevant evidence and a pressure-free next step. Respect a clear no.</p></details><details><summary>Offer & experiment framework</summary><p>Audience · problem · deliverables · exclusions · timing · price hypothesis. Then: one change · observation window · actual result · next decision.</p></details><button class="secondary" data-kit>${icon('Download')} Download field kit</button></section><section class="panel optional"><p class="eyebrow">OPTIONAL · EXTERNAL EDUCATION</p><h2>Explore LWA</h2><p>Separate education and products. None is required for OYO progression.</p>${cfg.mainUrl?`<a class="primary" href="${esc(cfg.mainUrl)}" target="_blank" rel="sponsored noopener noreferrer">${esc(cfg.mainTitle)} ${icon('ExternalLink')}</a>`:'<p>No main LWA link has been added yet.</p>'}<p class="fine">Referral disclosure: the OYO owner may earn a commission from these links. External products may require a separate purchase and are not included in OYO membership.</p></section></div><section class="resource-products"><h2 class="mt">Product resources</h2><div class="vault-grid">${cfg.products.map(item=>`<article class="panel"><p class="eyebrow">${item.world==='all'?'OPTIONAL RESOURCE':esc(worlds.find(w=>w.id===item.world)?.name||'RESOURCE')}</p><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><a class="secondary" href="${esc(item.url)}" target="_blank" rel="sponsored noopener noreferrer">Explore product ${icon('ExternalLink')}</a><p class="fine">External referral link · separate terms and pricing</p></article>`).join('')||'<p class="muted">Specific product resources will appear here when added.</p>'}</div></section>${state.resourceAdmin?`<section class="panel mt"><p class="eyebrow">OWNER CONTROLS</p><h2>Manage your LWA links</h2><p>Add your main referral link and up to 20 individual product links. Saving updates this Resources area for your players.</p><form id="resources-form"><label for="lwa-title">Main link label</label><input id="lwa-title" name="mainTitle" value="${esc(draft.mainTitle)}" maxlength="80" required><label for="lwa-main">Main LWA link <small>Leave empty to hide</small></label><input id="lwa-main" name="mainUrl" type="url" value="${esc(draft.mainUrl)}" placeholder="https://" maxlength="2000"><div>${draft.products.map((item,i)=>`<fieldset class="product-editor"><legend>Product ${i+1}</legend><label for="product-title-${i}">Product name</label><input id="product-title-${i}" name="title-${i}" value="${esc(item.title)}" maxlength="80" required><label for="product-url-${i}">Your product-specific referral URL</label><input id="product-url-${i}" name="url-${i}" type="url" value="${esc(item.url)}" maxlength="2000" required><label for="product-description-${i}">Description</label><textarea id="product-description-${i}" name="description-${i}" maxlength="300" rows="2">${esc(item.description)}</textarea><label for="product-world-${i}">Related world</label><select id="product-world-${i}" name="world-${i}"><option value="all" ${item.world==='all'?'selected':''}>All worlds</option>${worlds.map(w=>`<option value="${w.id}" ${item.world===w.id?'selected':''}>${w.name}</option>`).join('')}</select><button type="button" class="text-button" data-remove-product="${i}">Remove this product</button></fieldset>`).join('')}</div><div class="button-row"><button type="button" class="secondary" data-add-product ${draft.products.length>=20?'disabled':''}>Add product link</button><button class="primary">Save resource links ${icon('Check')}</button><button type="button" class="text-button" data-discard-resources>Discard edits & refresh</button></div></form></section>`:''}`;}
function readResourceDraft(){const f=new FormData($('#resources-form'));const existing=resourceDraft||resourceConfig();return {mainUrl:f.get('mainUrl')||'',mainTitle:f.get('mainTitle')||'Explore LWA',products:existing.products.map((p,i)=>({id:p.id,title:f.get('title-'+i)||'',url:f.get('url-'+i)||'',description:f.get('description-'+i)||'',world:f.get('world-'+i)||'all'}))};}
function membershipView(){return title('YOUR ADVENTURE PASS','Membership')+`<section class="panel membership"><div class="large-sigil">${icon('Crown')}</div><h2>${api.cloud?(state.entitlement?'Your pass is active.':'Continue with OYO.'):'Your device adventure is open.'}</h2><p>Explore nine business worlds, build your skills, work with evolving Guides, and keep a record of your real actions.</p><ul><li>18 field missions across nine worlds</li><li>Six Guides and nine evolving boss encounters</li><li>Proof Vault, skills, and achievement unlocks</li></ul><p>${api.cloud?'Membership access depends on the configured offer. A pass never bypasses proof or boss requirements.':'Your downloaded adventure works offline. Purchases and external links open when connected. No payment is taken inside this screen.'}</p><button class="primary" data-checkout ${state.entitlement?'disabled':''}>${state.entitlement?'Pass active':'View membership offer'} ${icon('ExternalLink')}</button><p class="fine">Pricing and checkout appear only through the configured payment provider. LWA is separate and always optional.</p></section>`;}
function profileView(){const p=state.game.profile;return title('YOUR CHARACTER','Make this adventure yours.')+`<div class="two-col"><section class="panel"><form id="profile-form"><div class="large-sigil">${icon(p.avatar)}</div><label for="name">Player name</label><input name="name" id="name" value="${esc(p.name)}" maxlength="32" required><fieldset><legend>Choose your sigil</legend><div class="avatar-picker">${['Compass','Feather','Gem','Flame','Shield','Crown'].map(a=>`<label class="avatar-choice"><input type="radio" name="avatar" value="${a}" ${p.avatar===a?'checked':''}><span>${icon(a)}<small>${a}</small></span></label>`).join('')}</div></fieldset><label for="path">Your starting path</label><select name="path" id="path">${['Creator','Affiliate','Service','Digital products','Coach','Local business'].map(x=>`<option ${p.path===x?'selected':''}>${x}</option>`).join('')}</select><label for="business">Your business or idea</label><textarea name="business" id="business" maxlength="500" rows="3">${esc(p.business)}</textarea><button class="primary">Save character ${icon('Check')}</button></form></section><section class="panel"><h2>${api.cloud?'Your account':'Saved on this device'}</h2><p>Your account and progress are saved with Firebase. Sign in on another device to continue. Account setup, password recovery, community chat, and live AI require internet.</p>${state.connectionError?`<p role="status">${esc(state.connectionError)}</p>`:''}${api.cloud?(state.user?`<p>Signed in as ${esc(state.user.email)}</p><button class="secondary" data-signout>${icon('LogOut')} Sign out</button>`:`<form id="auth-form"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" minlength="8" required><div class="button-row"><button class="primary" name="kind" value="signin">Sign in</button><button class="secondary" name="kind" value="signup">Create account</button></div></form>`):'<p>Your adventure saves in this browser without a password. Export a backup to protect against device loss or cleared browser data. An online account has a separate, owner-reviewed adventure.</p>'}${api.cloud?`<details><summary>Forgot your password?</summary><p>Enter your account email. Use the secure link in the email to choose a new password. We cannot display your old password. Check spam if the message does not arrive.</p><form id="reset-form"><label for="reset-email">Account email</label><input id="reset-email" name="email" type="email" autocomplete="email" required><button class="secondary">Send password-reset link</button></form></details>`:`<label for="restore-file">Restore a device backup</label><input id="restore-file" type="file" accept="application/json,.json"><p class="fine">Export includes your progress and evidence text. Download evidence attachments separately; they are not in the backup. Restoring replaces this device save.</p>`}<h2 class="mt">Game settings</h2><label class="answer"><input id="sound-pref" type="checkbox" ${prefs.sound?'checked':''}><span>Play unlock sounds</span></label><label class="answer"><input id="motion-pref" type="checkbox" ${prefs.motion?'checked':''}><span>Reduce motion</span></label><div class="button-row"><button class="secondary" data-install>${icon('Download')} Install app</button><button class="secondary" data-export>Export progress</button></div><p class="fine">On iPhone or iPad, use Safari → Share → Add to Home Screen. On supported desktop browsers, use the install icon in the address bar.</p>${!api.cloud?'<details><summary>Reset device adventure</summary><p>This removes this browser’s device progress and uploaded evidence files.</p><button class="danger" data-reset>Reset this device’s device save</button></details>':''}</section></div>`;}
function adminView(){if(!state.isOwner)return '<section class="panel"><h1>Owner access only</h1><p>This area is not available to this account.</p></section>';const a=adminOverview?.announcement||state.announcement||{title:'',body:'',enabled:false};return title('PRIVATE · YOUR ACCOUNT ONLY','Owner Admin',`<button class="secondary" data-admin-refresh>Refresh overview</button>`)+`<div class="stats-grid"><section class="panel"><span>PLAYERS</span><strong>${adminOverview?.playerCount??'—'}</strong></section><section class="panel"><span>PROOFS WAITING</span><strong>${adminOverview?.pendingProofs??'—'}</strong></section></div><div class="two-col"><section class="panel"><h2>Manage your game</h2><div class="admin-links"><button class="secondary" data-nav="resources">Add / edit LWA & product links ${icon('ExternalLink')}</button><button class="secondary" data-admin-proofs>Review player proof ${icon('ShieldCheck')}</button></div><p class="fine">Only your registered owner account can use these controls. Players cannot grant themselves admin access.</p><button class="secondary" data-nav="community">Manage community chat</button><h3>Game content and paid offers</h3><p>Lessons, worlds, Guide instructions, and payment-provider setup remain in the source code. Those changes require an updated deployment; this editor does not grant arbitrary code execution or change player XP.</p></section><section class="panel"><h2>Player announcement</h2><p>Add or update a message for your players. This announcement becomes visible to signed-in players after they refresh.</p><form id="announcement-form"><label for="announcement-title">Title</label><input id="announcement-title" name="title" maxlength="100" value="${esc(a.title)}"><label for="announcement-body">Message</label><textarea id="announcement-body" name="body" maxlength="1500" rows="6">${esc(a.body)}</textarea><label class="answer"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>Show this announcement to players</label><button class="primary">Save announcement</button></form></section></div>`;}
function reviewView(){return title('AUTHORISED REVIEWERS','Proof review queue',`<button class="secondary" data-load-queue>Refresh queue</button>`)+(!state.reviewer?'<p>This area requires a reviewer account.</p>':`<div class="vault-grid">${queue.map(p=>`<article class="panel"><h2>${esc(missions.find(m=>m.id===p.missionId)?.title)}</h2><p>${esc(p.summary)}</p>${p.evidence.map((x,i)=>`<p><b>${esc(missions.find(m=>m.id===p.missionId).criteria[i])}</b><br>${esc(x)}</p>`).join('')}${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open submitted link</a>`:''}${p.attachment?`<button class="secondary" data-review-file="${p.id}">Download submitted file</button>`:''}<form class="review-form" data-proof="${p.id}" data-uid="${esc(p.uid)}"><label for="feedback-${p.id}">Review feedback</label><textarea name="feedback" id="feedback-${p.id}" minlength="10" maxlength="2000" required></textarea><button class="primary" name="decision" value="approve">Approve proof</button><button class="secondary" name="decision" value="reject">Request revision</button></form></article>`).join('')||'<p>Refresh to load pending proofs. You cannot review your own submissions.</p>'}</div>`);}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function bind(){
 $('#community-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,text=new FormData(form).get('text'),id=form.dataset.id||crypto.randomUUID();form.dataset.id=id;run(async()=>{await api.sendChat(text,id);form.reset();delete form.dataset.id;});});
 $('#community-text')?.addEventListener('input',()=>{delete $('#community-form').dataset.id;});
 $('[data-community-reports]')?.addEventListener('click',()=>run(async()=>{communityReports=await api.getChatReports();paintCommunity();}));

 $('[data-admin-refresh]')?.addEventListener('click',()=>run(async()=>{adminOverview=await api.getAdminOverview();render();}));
 $('[data-admin-proofs]')?.addEventListener('click',()=>run(async()=>{queue=await api.reviewQueue();go('review');}));
 $('#announcement-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await api.saveAnnouncement({title:f.get('title'),body:f.get('body'),enabled:f.get('enabled')==='on'});adminOverview=await api.getAdminOverview();render();notify('Announcement saved.');});});

 $('[data-add-product]')?.addEventListener('click',()=>{resourceDraft=readResourceDraft();resourceDraft.products.push({id:crypto.randomUUID(),title:'',url:'',description:'',world:'all'});render();});
 document.querySelectorAll('[data-remove-product]').forEach(b=>b.onclick=()=>{resourceDraft=readResourceDraft();resourceDraft.products.splice(Number(b.dataset.removeProduct),1);render();});
 $('#resources-form')?.addEventListener('submit',e=>{e.preventDefault();const resources=readResourceDraft();run(async()=>{await api.saveResources(resources);resourceDraft=null;render();notify('Your resource links are saved for players.');});});
 $('[data-discard-resources]')?.addEventListener('click',()=>run(async()=>{resourceDraft=null;await api.refreshPlayer();}));
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{selectedWorld=Number(b.dataset.world);render();});document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{selectedMission=b.dataset.mission;go('mission');});document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{selectedGuide=b.dataset.guide;go('guides');});document.querySelectorAll('[data-select-guide]').forEach(b=>b.onclick=()=>{selectedGuide=b.dataset.selectGuide;render();});
 $('[data-continue]')?.addEventListener('click',()=>{const m=missions.find(x=>x.world===selectedWorld&&missionState(state.game,x.id).status!=='verified');if(m){selectedMission=m.id;go('mission')}else go('boss');});
 $('[data-step]')?.addEventListener('click',()=>run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:0})));
 $('#practice-form')?.addEventListener('submit',e=>{e.preventDefault();run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:1,answer:Number(new FormData(e.target).get('answer'))}));});
 $('#draft')?.addEventListener('input',e=>sessionStorage.setItem('draft-'+(state.user?.uid||'signed-out')+'-'+selectedMission,e.target.value));
 $('#build-form')?.addEventListener('submit',e=>{e.preventDefault();const draft=new FormData(e.target).get('draft');run(async()=>{await api.action({type:'step',missionId:selectedMission,expectedStep:2,draft});sessionStorage.removeItem('draft-'+(state.user?.uid||'signed-out')+'-'+selectedMission);});});
 $('#irl-form')?.addEventListener('submit',e=>{e.preventDefault();run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:3,confirmed:true}));});
 $('#proof-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('file');run(async()=>{await api.submitProof(selectedMission,{summary:f.get('summary'),evidence:[0,1,2].map(i=>f.get('evidence-'+i)),url:f.get('url')},file?.size?file:null);notify('Your proof is safely in the vault.');});});
 document.querySelectorAll('[data-simulate]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('I have completed the real-world action and checked every evidence criterion. This records my own review, not owner verification.'))return;await api.simulateReview(b.dataset.simulate);sound();notify('Self-review recorded. Your next device step is unlocked.');}));
 $('[data-next]')?.addEventListener('click',()=>{const m=missions.find(x=>x.id===selectedMission);selectedWorld=m.world;const next=missions.find(x=>x.world===m.world&&missionState(state.game,x.id).status!=='verified');if(next){selectedMission=next.id;render()}else go('boss');});
 $('[data-next-world]')?.addEventListener('click',()=>{if(selectedWorld<8){selectedWorld++;go('map')}else go('progress');});
 $('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const message=new FormData(e.target).get('message');run(async()=>{await api.chat(selectedGuide,message);$('#message').value='';$('.chat-log').scrollTop=99999;});});
 $('#boss-form')?.addEventListener('submit',e=>{e.preventDefault();const answer=new FormData(e.target).get('answer');run(async()=>{const r=await api.fight(worlds[selectedWorld].id,answer,Number(new FormData(e.target).get('choice')));if(r.passed)sound();notify(r.feedback,!r.passed);});});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{vaultFilter=b.dataset.filter;render()});document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>run(async()=>{const p=state.proofs.find(x=>x.id===b.dataset.file);download(await api.proofFile(p),p.fileName||p.attachment.name);}));
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download(api.exportSave(),'oyo-progress.json'));
 $('[data-kit]')?.addEventListener('click',()=>download(new Blob(['OYO FIELD KIT\n\nAUDIENCE INTERVIEW\nTell me about the last time you faced this problem. What did you try? What was difficult?\n\nOFFER\nAudience / problem / deliverables / exclusions / timeframe / price hypothesis / next step\n\nEXPERIMENT\nHypothesis / one change / observation window / actual result / next experiment\n\nNo income guarantees. Respect consent and privacy.'],{type:'text/plain'}),'oyo-field-kit.txt'));
 $('[data-checkout]')?.addEventListener('click',()=>run(()=>api.checkout()));
 $('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const profile=Object.fromEntries(new FormData(e.target));run(async()=>{await api.action({type:'profile',profile});notify('Character saved.');});});
 $('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),kind=e.submitter.value;run(async()=>{await api.auth(kind,f.get('email'),f.get('password'));notify(kind==='reset'?'If the address has an account, a reset email will arrive.':'Welcome to your adventure.');});});
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>api.switchMode(b.dataset.mode));
 $('#reset-form')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api.auth('reset',new FormData(e.target).get('email'),'');notify('If this address has an account, a password-reset email will arrive.');});});
 $('#restore-file')?.addEventListener('change',e=>{const f=e.target.files[0];if(f&&confirm('Replace the current device adventure with this backup?'))run(()=>api.importSave(f));});
 $('[data-signout]')?.addEventListener('click',()=>run(()=>api.signOut()));
 ['sound','motion'].forEach(k=>$('#'+k+'-pref')?.addEventListener('change',e=>{prefs[k]=e.target.checked;localStorage.setItem('oyo-preferences',JSON.stringify(prefs));render();}));
 $('[data-install]')?.addEventListener('click',()=>run(async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else notify('Use your browser’s Install app or Add to Home Screen option. Installation requires HTTPS or localhost.');}));
 $('[data-reset]')?.addEventListener('click',()=>{if(confirm('Delete this browser’s device progress and proof files? This cannot be undone.'))run(()=>api.resetLocal());});
 $('[data-refresh]')?.addEventListener('click',()=>run(()=>api.refreshPlayer()));
 $('[data-load-queue]')?.addEventListener('click',()=>run(async()=>{queue=await api.reviewQueue();render();}));
 document.querySelectorAll('[data-review-file]').forEach(b=>b.onclick=()=>run(async()=>{const p=queue.find(x=>x.id===b.dataset.reviewFile);download(await api.proofFile(p),p.attachment.name);}));
 document.querySelectorAll('.review-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const data={uid:f.dataset.uid,proofId:f.dataset.proof,approved:e.submitter.value==='approve',feedback:new FormData(f).get('feedback')};run(async()=>{await api.reviewProof(data);queue=await api.reviewQueue();render();notify('Review saved.');});});
}
render();api.initBackend(s=>{if(state.user?.uid!==s.user?.uid){adminOverview=null;queue=[];resourceDraft=null;hydrated=false;}state=s;if(!hydrated){selectedWorld=worlds.find(w=>worldOpen(s.game,w.index)&&!s.game.bosses[w.id]?.won)?.index??8;selectedMission=currentMission()?.id||missions[selectedWorld*2].id;hydrated=true;}render();}).catch(e=>notify(e.message,true));
if('serviceWorker' in navigator&&import.meta.env.PROD)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>notify('Offline shell could not be installed. The online game still works.',true)));

function communityView(){return title('YOUR COMMUNITY','The player lounge')+`<section class="panel"><p>Share wins, ask questions, and support other players. Messages and player names are visible to signed-in players. Keep customer details and private information out of this room.</p>${!state.user?'<button class="primary" data-nav="profile">Sign in to join</button>':`<p id="community-status" role="status">${navigator.onLine?'Connecting to community…':'Reconnect to use community chat.'}</p><div id="community-log" class="chat-log" aria-label="Community messages"></div><form id="community-form"><label for="community-text">Message</label><textarea id="community-text" name="text" minlength="1" maxlength="800" required></textarea><button class="primary">Send message</button></form>${state.isOwner?'<button class="secondary" data-community-reports>Load reported messages</button><div id="community-reports"></div>':''}`}</section>`;}
function syncCommunity(){const uid=view==='community'&&navigator.onLine?state.user?.uid:null;if(uid!==communityUid){communityStop?.();communityStop=null;communityUid=uid;communityMessages=[];communityReports=[];if(uid){try{communityStop=api.watchGamerChat(messages=>{communityMessages=messages;paintCommunity();},e=>{if($('#community-status'))$('#community-status').textContent=e.message;});}catch(e){notify(e.message,true);}}}paintCommunity();}
function paintCommunity(){const log=$('#community-log');if(!log)return;log.innerHTML=communityMessages.map(m=>`<article class="chat"><b>${esc(m.playerName)}</b><p class="prewrap">${esc(m.text)}</p>${!m.removed?`<button class="text-button" data-community-report="${esc(m.id)}">Report</button>${state.isOwner?`<button class="text-button" data-community-remove="${esc(m.id)}">Remove</button><button class="text-button" data-community-mute="${esc(m.id)}">Remove & mute 24 hours</button>`:''}`:''}</article>`).join('')||'<p>No messages yet.</p>';if($('#community-status'))$('#community-status').textContent=navigator.onLine?'Live community':'Reconnect to use community chat.';
 document.querySelectorAll('[data-community-report]').forEach(b=>b.onclick=()=>{const reason=prompt('Why are you reporting this message?');if(reason)run(async()=>{await api.reportChat(b.dataset.communityReport,reason);notify('Report sent to the owner.');});});
 for(const action of ['remove','mute'])document.querySelectorAll('[data-community-'+action+']').forEach(b=>b.onclick=()=>run(()=>api.moderateChat(b.dataset[action==='remove'?'communityRemove':'communityMute'],action==='mute')));
 const reports=$('#community-reports');if(reports){reports.innerHTML=communityReports.map(r=>`<article class="chat"><p>${esc(r.messageText)}</p><p>Report: ${esc(r.reason)}</p><button data-resolve-community="${esc(r.id)}">Resolve report</button></article>`).join('');document.querySelectorAll('[data-resolve-community]').forEach(b=>b.onclick=()=>run(async()=>{await api.resolveChatReport(b.dataset.resolveCommunity);communityReports=await api.getChatReports();paintCommunity();}));}}
